// Generates src/services/themes/base16Schemes.ts — the Base16 schemes that
// ship with LIQUEAMP as built-in themes — from the official scheme files of
// tinted-theming/schemes (MIT licence, branch spec-0.11). Colors are copied
// exactly; nothing is invented or adjusted.
//
//   node scripts/import-base16-themes.mjs
//
// To add a built-in theme: add its file name (without .yaml) to SLUGS, run
// the script, commit the regenerated file.
import { writeFileSync } from 'node:fs';
import { parse } from 'yaml';

const SOURCE = 'https://raw.githubusercontent.com/tinted-theming/schemes/spec-0.11/base16';

// Widely used schemes: 15 dark, 5 light.
const SLUGS = [
  'catppuccin-mocha',
  'dracula',
  'nord',
  'gruvbox-dark-medium',
  'onedark',
  'solarized-dark',
  'tokyo-night-dark',
  'rose-pine',
  'everforest',
  'kanagawa',
  'monokai',
  'ayu-dark',
  'material-palenight',
  'tomorrow-night',
  'github-dark',
  'catppuccin-latte',
  'gruvbox-light-medium',
  'solarized-light',
  'one-light',
  'rose-pine-dawn',
];

const KEYS = Array.from({ length: 16 }, (_, i) => `base0${i.toString(16).toUpperCase()}`);
const hex = (v) => {
  const s = String(v).trim().replace(/^#/, '').toLowerCase();
  if (!/^[0-9a-f]{6}$/.test(s)) throw new Error(`bad color ${v}`);
  return `#${s}`;
};

const schemes = [];
for (const slug of SLUGS) {
  const res = await fetch(`${SOURCE}/${slug}.yaml`);
  if (!res.ok) throw new Error(`${slug}: HTTP ${res.status}`);
  const doc = parse(await res.text());
  if (doc.system !== 'base16') throw new Error(`${slug}: not a base16 scheme`);
  const palette = Object.fromEntries(KEYS.map((k) => [k, hex(doc.palette[k])]));
  schemes.push({ slug, name: doc.name, author: doc.author, variant: doc.variant === 'light' ? 'light' : 'dark', palette });
  console.log(`${slug.padEnd(22)} ${doc.name}`);
}

const body = schemes
  .map(
    (s) => `  {
    slug: ${JSON.stringify(s.slug)},
    name: ${JSON.stringify(s.name)},
    author: ${JSON.stringify(s.author)},
    variant: ${JSON.stringify(s.variant)},
    palette: {
${KEYS.map((k) => `      ${k}: '${s.palette[k]}',`).join('\n')}
    },
  },`,
  )
  .join('\n');

writeFileSync(
  new URL('../src/services/themes/base16Schemes.ts', import.meta.url),
  `// GENERATED by scripts/import-base16-themes.mjs — do not edit by hand.
// Source: tinted-theming/schemes (spec-0.11), MIT licence,
// ${SOURCE}/<slug>.yaml. Each scheme keeps its author credit.
import type { Base16Palette } from '../../types/theme';

export interface Base16Scheme {
  slug: string;
  name: string;
  author: string;
  variant: 'dark' | 'light';
  palette: Base16Palette;
}

export const BASE16_SCHEMES: readonly Base16Scheme[] = [
${body}
];
`,
);
console.log(`wrote ${schemes.length} schemes`);
